# Generates test/scipy/test_stats_final_methods.py with scipy 1.18.1 (PermutationMethod wiring).
import numpy as np, scipy.stats as st
x = [1., 2., 3., 4., 5., 6., 7.]; y = [2., 1., 4., 3., 7., 5., 6.]
r = st.pearsonr(x, y, method=st.PermutationMethod(n_resamples=99999, rng=1))
a = st.pearsonr(x, y)
o = ["# Copyright (C) 2026 the Typhon authors",
"# Expected values generated by test/scipy/gen_stats_final_methods.py (scipy 1.18.1).",
"import scipy.stats as st", "", "@test", "def test_pearsonr_permutation():",
f"    x = {x}", f"    y = {y}",
"    r = st.pearsonr(x, y, method=st.PermutationMethod(n_resamples=99999, rng=1))",
f"    assert abs(r.statistic - {float(a.statistic)!r}) < 1e-12",
f"    assert abs(r.pvalue - {float(a.pvalue)!r}) < 0.02  # exact enumeration (7! < n_resamples)",
f"    assert abs(r.pvalue - {float(r.pvalue)!r}) < 1e-12"]
print("\n".join(o))
